import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Big picture overview","description":"","frontmatter":{"title":"Big picture overview"},"headers":[],"relativePath":"docs/overview/big-picture-overview.md","filePath":"docs/overview/big-picture-overview.md","lastUpdated":1794508483000}'),i={name:"docs/overview/big-picture-overview.md"};function n(s,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="big-picture-overview" tabindex="-1">Big picture overview <a class="header-anchor" href="#big-picture-overview" aria-label="Permalink to &quot;Big picture overview&quot;">​</a></h1><p>OrbySystems turns the financial records you already have into a private place to explore your household&#39;s money. Start with supported statements or exports. More history improves the view of recurring spending, income and investment patterns; overlapping bank and brokerage periods make the connected picture more useful. You do not have to recreate that history in forms.</p><h2 id="projects-in-one-picture-out" tabindex="-1">Projects in, one picture out <a class="header-anchor" href="#projects-in-one-picture-out" aria-label="Permalink to &quot;Projects in, one picture out&quot;">​</a></h2><p>Keep each kind of record in its own project:</p><ul><li><strong>Banking + Credit Cards</strong> holds bank and credit-card activity.</li><li><strong>Investment</strong> holds brokerage and retirement-account activity.</li><li><strong>Assets / Liabilities</strong> tracks property, other assets and debts.</li><li><strong>Retail Purchases</strong> breaks down supported order histories, currently Amazon.</li><li><strong>General Documents</strong> lets you ask AI about personal documents, including trust documents.</li></ul><p>A <strong>Standard Workbook</strong> brings finance projects together for combined spending, investment and net-worth views. A <strong>Retirement Planning</strong> workbook uses selected source projects for a retirement outlook and scenario planning. The records stay in their projects, so you can add another account or statement without rebuilding the workbook.</p><p>Start with the example household to try dashboards, recipes and Demo Retirement without using personal data. Demo and real projects stay separate.</p><h2 id="start-with-a-real-question" tabindex="-1">Start with a real question <a class="header-anchor" href="#start-with-a-real-question" aria-label="Permalink to &quot;Start with a real question&quot;">​</a></h2><ul><li><em>Where does our money go each month?</em></li><li><em>What could we change without changing the life we like?</em></li><li><em>What did we actually earn after deposits and withdrawals?</em></li><li><em>Could we take a break, change careers, or retire—and what would have to change?</em></li></ul><p>Recipes and calculation tools prepare the financial results; AI helps explain them. Evidence marks show the support behind numbers in an answer. Inspect the records and assumptions when a result needs review.</p><h2 id="local-by-default" tabindex="-1">Local by default <a class="header-anchor" href="#local-by-default" aria-label="Permalink to &quot;Local by default&quot;">​</a></h2><p>With the built-in models ready, OrbySystems can analyze local records without an account or cloud model. Optional online tools, statement downloads, updates, reporting and activation use the network. <a href="/docs/settings/privacy">Privacy settings</a> explains the controls and reporting choices.</p><p>An account manages services such as licenses and recovery; it does not upload your financial projects. <a href="/docs/settings/license">License settings</a> explains activation. Importing and keeping records is separate from the history range available to a particular analysis.</p><p>Ready to begin? <a href="/docs/getting-started/install-orby">Install OrbySystems</a>, then <a href="/docs/getting-started/create-first-project">create your first project</a>.</p>',14)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
